      { labelAr: 'الفِعْلُ المُضَارِعُ المَبْنِيُّ لِلْمَجْهُولِ', formulaAr: 'ضَمُّ الأَوَّلِ + فَتْحُ مَا قَبْلَ الآخِرِ (يُكْتَبُ)' }
