        solution: '• الجُمْلَةُ بَعْدَ التَّحْوِيلِ: «قُرِئَتِ القِصَّةُ» (أَوْ قُرِئَ الكِتَابُ).\n• القِصَّةُ: نَائِبُ فَاعِلٍ مَرْفُوعٌ وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ عَلَى آخِرِهِ.'
