        solution: 'السَّبَبُ: نَقْصُ الفِيتَامِينِ (D) وَعُنْصُرِ الكَالْسِيُومِ فِي غِذَائِهِ، إِضَافَةً إِلَى عَدَمِ التَّعَرُّضِ لِأَشِعَّةِ الشَّمْسِ.\nالعِلاَجُ:\n1. تَنَاوُلُ الأَغْذِيَةِ الغَنِيَّةِ بِالكَالْسِيُومِ كَالْحَلِيبِ وَمُشْتَقَّاتِهِ وَالبَيْضِ.\n2. التَّعَرُّضُ المُنْتَظَمُ لِأَشِعَّةِ الشَّمْسِ الصَّبَاحِيَّةِ.'
