    summaryAr: `تَبْدُو الشَّمْسُ وَكَأَنَّهَا تَتَحَرَّكُ فِي السَّمَاءِ مِنَ الشَّرْقِ إِلَى الغَرْبِ (الحَرَكَةُ الظَّاهِرِيَّةُ). لَكِنَّ الحَقِيقَةَ أَنَّ الأَرْضَ هِيَ الَّتِي تَدُورُ حَوْلَ مِحْوَرِهَا المَائِلِ مِنْ الغَرْبِ إِلَى الشَّرْقِ خِلاَلَ 24 سَاعَةً، مِمَّا يَنْتُجُ عَنْهُ تَعَاقُبُ اللَّيْلِ وَالنَّهَارِ.`,
