      'Grammaire - L\'adjectif qualificatif (épithète ou attribut) : l\'adjectif précise le nom. Exemple : "La gazelle sauvage est rapide." (sauvage = épithète, rapide = attribut).',
      'Conjugaison - Le présent de l\'indicatif : les verbes du 1er groupe (-er) prennent les terminaisons : -e, -es, -e, -ons, -ez, -ent. (Exemple : "Le fennec habite dans le désert").',
