      'Forme négative : encadrer le verbe par "ne ... pas" (ou n\'... pas) / "ne ... plus" / "ne ... jamais". Exemple : "Le lion mange de l\'herbe" ➔ "Le lion ne mange pas de l\'herbe".',
      'Complément d\'Objet Direct (C.O.D.) : répond à la question "Sujet + Verbe + QUI / QUOI ?". Exemple : "Massinissa regarde la gazelle" (regarde quoi ? la gazelle = C.O.D.).',
      'Complément d\'Objet Indirect (C.O.I.) : répond à "À QUI / À QUOI / DE QUI / DE QUOI ?". Exemple : "Il parle à son ami" (parle à qui ? à son ami = C.O.I.).',
