      'تَطَابُقُ الصِّفَةِ: تَتْبَعُ الصِّفَةُ المَوْصُوفَ فِي أَرْبَعَةِ أَشْيَاءَ: 1) الحَرَكَةِ الإِعْرَابِيَّةِ (رَفْعاً، نَصْباً، جَرّاً)، 2) التَّعْرِيفِ وَالتَّنْكِيرِ (الـ)، 3) التَّذْكِيرِ وَالتَّأْنِيثِ، 4) العَدَدِ (مُفْرَدٌ، مُثَنًّى، جَمْعٌ).',
      'حُرُوفُ الجَرِّ: (مِنْ، إِلَى، عَنْ، عَلَى، فِي، البَاءُ، اللَّامُ، الكَافُ).',
      'الاسْمُ المَجْرُورُ: اسْمٌ يَأْتِي بَعْدَ حَرْفِ الجَرِّ، وَعَلَامَةُ جَرِّهِ الكَسْرَةُ الظَّاهِرَةُ (أَوْ اليَاءُ فِي المُثَنَّى وَجَمْعِ المُذَكَّرِ السَّالِمِ).'
