export const COURSES_DATA: CourseLesson[] = [
  ...COURSES_1AP,
  ...COURSES_2AP,
  ...COURSES_3AP,
  ...BASE_COURSES_DATA.map((lesson, idx) => {
    let trimester: 1 | 2 | 3 = lesson.trimester || 1;
    if (!lesson.trimester) {
      if (lesson.id.includes('fractions') || lesson.id.includes('decimals') || lesson.id.includes('history') || lesson.id.includes('projet2') || lesson.id.includes('unit2') || idx % 3 === 1) {
        trimester = 2;
      } else if (lesson.id.includes('exam') || lesson.id.includes('projet3') || lesson.id.includes('unit3') || idx % 3 === 2) {
        trimester = 3;
      }
    }
    return {
      ...lesson,
      trimester
    };
  })
];








